@@ -530,6 +530,7 @@ impl Context {
     ) -> Result<Typed, NatDefinitionElabError> {
         enum Task<'a> {
             Ascription(&'a Syntax, Option<Expr>),
+            AscribedValue(Expr),
             Projection(Name, Option<Expr>, bool),
             RecordType(record_terms::RecordParts<'a>, Option<Expr>),
             RecordNext(record_terms::RecordBuild<'a>),
@@ -732,8 +733,25 @@ impl Context {
                     if let Some(expected) = expected {
                         self.constrain(&type_.value, &expected)?;
                     }
+                    tasks.push(Task::AscribedValue(type_.value.clone()));
                     tasks.push(Task::Visit(syntax, Some(type_.value), true));
                 }
+                Task::AscribedValue(annotation) => {
+                    let term = values.pop().expect("ascribed term follows its annotation");
+                    // Expected types guide inference but closed constraints are
+                    // left to K1. Retain this assertion in the checked term,
+                    // including when the surrounding program ignores its value.
+                    values.push(Typed {
+                        value: Expr::let_e(
+                            Name::anonymous(),
+                            annotation.clone(),
+                            term.value,
+                            Expr::bvar(0).expect("fixed ascription identity binder"),
+                            false,
+                        ),
+                        type_: annotation,
+                    });
+                }
                 Task::RecordType(parts, expected) => {
                     let type_ = values.pop().expect("record type visit");
                     self.sort_level(&type_)?;
diff --git a/crates/fln/tests/source_record_literals.rs b/crates/fln/tests/source_record_literals.rs
index 0550dfd..5fb98a5 100644
--- a/crates/fln/tests/source_record_literals.rs
+++ b/crates/fln/tests/source_record_literals.rs
@@ -206,3 +206,26 @@ fn unknown_fields_do_not_resolve_as_arbitrary_namespace_methods() {
         assert_eq!(e.environment().logical_root(&KVMap::new()), root);
     }
 }
+
+#[test]
+fn expression_ascriptions_cannot_disappear_before_kernel_checking() {
+    let e = engine();
+    for text in [
+        "def bad : Nat := (1 : String)",
+        "def bad : Nat := let x := (1 : String); 0",
+        "def ignored (x : String) : Nat := 0\ndef bad : Nat := ignored (1 : String)",
+        "def bad : Nat := ((fun x => x) : String -> String) 1",
+    ] {
+        let result = e.check_source_files(
+            &[text.as_bytes()],
+            &KVMap::new(),
+            SourceCheckLimits::new(limits()),
+        );
+        let refusal = result.expect_err("a false source ascription must reach rejection");
+        assert_eq!(
+            refusal.disposition(),
+            ("kernel-rejection", true, 1),
+            "{text}: {refusal:?}"
+        );
+    }
+}
